const b = $json.body || $json;
const paquetes = new Set(['presencia', 'completo', 'mantenimiento']);
const paquete = String(b.paquete || b.plan || 'presencia').trim().toLowerCase();
const cliente = String(b.cliente || b.slug || '').trim();
const marca = String(b.marca || b.nombre_negocio || '').trim();
const whatsapp = String(b.whatsapp || '').trim();
const jobAudit = String(b.jobAudit || b.job_audit || '').trim();
const urlNegocio = String(b.url || '').trim();
if (!paquetes.has(paquete)) {
  return [{ json: { ok: false, error: 'paquete inválido', paquetes: [...paquetes] } }];
}
if (!cliente && !marca) {
  return [{ json: { ok: false, error: 'falta cliente o marca' } }];
}
const slug = (cliente || marca).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
return [{ json: {
  ok: true,
  sistema: '07-presencia-digital',
  etapa: 'alta',
  jobId: `PRE-${Date.now()}`,
  slug,
  marca: marca || slug,
  paquete,
  whatsapp,
  jobAudit,
  urlNegocio,
  status: 'queued',
  apps: ['creador-de-landings', 'vercel/netlify', 'gbp', 'whatsapp', 'clientes/'],
  entregables: paquete === 'completo'
    ? ['landing_url', 'gbp_ok', 'wasap_task']
    : ['landing_url', 'gbp_ok'],
  todo: 'TODO: crear clientes/{slug}/ + disparar landing pipeline',
  at: new Date().toISOString()
}}];
